function fewestStrides(target: number): number {
  const t = Math.abs(target);
  let k = Math.max(0, Math.floor((Math.sqrt(8 * t + 1) - 1) / 2));
  // the float root may be one short; nudge until the sum reaches t
  while ((k * (k + 1)) / 2 < t) k++;
  while (((k * (k + 1)) / 2 - t) % 2 !== 0) k++;
  return k;
}

